INSERT INTO `menu_product_head` (`menu_product_head_id`, `created_at`, `updated_at`, `name_head_menu_thai`, `name_head_menu_eng`, `img_head_menu_eng`, `title_head_menu_thai`, `title_head_menu_eng`, `content_head_menu_thai`, `content_head_menu_eng`) VALUES
(3, '2020-11-19 00:18:21', '2021-08-04 04:15:23', 'อาหารจานหลักเพื่อสุขภาพ', 'eatfit : HOT MEALS', 'local/storage/app/image_head_menu/mqKDRT1c1RQ81xaivRWSnBhHkcr6XVrD3I7J2nPV.jpeg', 'อร่อยแบบสุขภาพดี มีความสุขในทุกมื้อ', 'Control your weight without losing food pleasure', '<p>อร่อยแบบสุขภาพดี มีความสุขในทุกมื้อ </p>', '<p>Control your weight without losing food pleasure</p>'),
(4, '2020-11-19 00:20:36', '2021-08-04 04:15:32', 'อาหารว่างเพื่อสุขภาพ', 'eatfit : LIGHT MEALS', 'local/storage/app/image_head_menu/FWTFMOOLEc1uJU0o5H1ifEl03Eo5EZvhdCN4I8Rq.jpg', 'อร่อยจนน่าทึ่ง ดึงดูดทุกสายตา', 'The tastiest way to look awesome', '<p>อร่อยจนน่าทึ่ง ดึงดูดทุกสายตา</p>', '<p>The tastiest way to look awesome</p>'),
(5, '2020-11-19 00:22:23', '2021-08-04 04:15:45', 'เครื่องดื่มเพื่อสุขภาพ', 'eatfit : HEALTHY DRINKS', 'local/storage/app/image_head_menu/hQ0NQRMdRVFBLG2psGBFeNTfi9c2o5Hf3ARf98Gk.jpeg', 'ดื่มแล้วดี ต้องเฮลธ์ตี้ดริ้งค์', 'Say “cheers” to nutrition', '<p>ดื่มแล้วดี ต้องเฮลธ์ตี้ดริ้งค์</p>', '<p>Say “cheers” to nutrition</p>'),
(6, '2020-11-19 00:25:31', '2021-08-04 04:18:26', 'เครื่องดื่มเพิ่มโปรตีนเพื่อสุขภาพ', 'eatfit : CHICKEN BREAST SMOOTHIES', 'local/storage/app/image_head_menu/cvOijiRePj3kwX55mv4mz1WiLTUvFPJkJO6EqHMh.jpg', 'เสริมสร้างกล้ามเนื้อด้วยโปรตีนคุณภาพดีที่จำเป็นต่อร่างกาย', 'Build muscle with high-quality protein', '<p>เสริมสร้างกล้ามเนื้อด้วยโปรตีนคุณภาพดีที่จำเป็นต่อร่างกาย</p>', '<p>Build muscle with high-quality protein, which are necessary for the body</p>'),
(7, '2020-11-19 00:26:11', '2021-08-04 04:16:01', 'คู่หูสุดคุ้ม', 'eatfit : DOUBLE VALUE SETS', 'local/storage/app/image_head_menu/KBxhpFYJSFYPCneqsu2OUh0M8p7l6I51zR6OjMql.jpeg', 'เลือกคู่หูที่ใช่ ได้รูปร่างที่ชอบ', 'Save as you sharpen up your shape', '<p>เลือกคู่หูที่ใช่ ได้รูปร่างที่ชอบ</p>', '<p>Save as you sharpen up your shape</p>');
